PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS sim_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sim_models(hash TEXT PRIMARY KEY,created_ms INTEGER NOT NULL,profile_json TEXT NOT NULL,financial_mode TEXT NOT NULL DEFAULT 'SIM' CHECK(financial_mode='SIM'));
CREATE TABLE IF NOT EXISTS sim_configs(hash TEXT PRIMARY KEY,created_ms INTEGER NOT NULL,config_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sim_runs(run_id TEXT PRIMARY KEY,created_ms INTEGER NOT NULL,last_ms INTEGER NOT NULL,status TEXT NOT NULL,restarts INTEGER NOT NULL DEFAULT 0,model_hash TEXT NOT NULL,config_hash TEXT NOT NULL,financial_mode TEXT NOT NULL DEFAULT 'SIM' CHECK(financial_mode='SIM'));
CREATE TABLE IF NOT EXISTS sim_segments(id INTEGER PRIMARY KEY,run_id TEXT NOT NULL,started_ms INTEGER NOT NULL,stopped_ms INTEGER,status TEXT NOT NULL,recovery_json TEXT,model_hash TEXT NOT NULL,config_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sim_events(id INTEGER PRIMARY KEY,run_id TEXT NOT NULL,event_sequence INTEGER NOT NULL,at_ms REAL NOT NULL,kind TEXT NOT NULL,payload_json TEXT NOT NULL,financial_mode TEXT NOT NULL DEFAULT 'SIM' CHECK(financial_mode='SIM'),UNIQUE(run_id,event_sequence));
CREATE TABLE IF NOT EXISTS sim_safety(run_id TEXT PRIMARY KEY,at_ms REAL NOT NULL,event_sequence INTEGER NOT NULL,sha256 TEXT NOT NULL,payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sim_checkpoints(run_id TEXT NOT NULL,slot INTEGER NOT NULL CHECK(slot IN(0,1)),generation INTEGER NOT NULL,saved_ms INTEGER NOT NULL,clean INTEGER NOT NULL,model_hash TEXT NOT NULL,sha256 TEXT NOT NULL,payload_json TEXT NOT NULL,PRIMARY KEY(run_id,slot));
CREATE TABLE IF NOT EXISTS sim_decisions(id INTEGER PRIMARY KEY,run_id TEXT NOT NULL,second_ms INTEGER NOT NULL,strategy TEXT NOT NULL,side TEXT NOT NULL,raw_trigger INTEGER NOT NULL,baseline_ok INTEGER,baseline_reason TEXT NOT NULL,timing_status TEXT NOT NULL,timing_reason TEXT NOT NULL,entry_reason TEXT NOT NULL,observations INTEGER NOT NULL DEFAULT 1,signal_min REAL,signal_max REAL,available_raw TEXT NOT NULL,notional_usd INTEGER NOT NULL,model_hash TEXT NOT NULL,financial_mode TEXT NOT NULL DEFAULT 'SIM' CHECK(financial_mode='SIM'),UNIQUE(run_id,second_ms,strategy,side,baseline_reason,timing_status,timing_reason,entry_reason));
CREATE TABLE IF NOT EXISTS sim_intents(run_id TEXT NOT NULL,intent_id TEXT NOT NULL,kind TEXT NOT NULL,state TEXT NOT NULL,created_ms REAL NOT NULL,notional_raw TEXT,deadline_sec INTEGER,payload_json TEXT NOT NULL,financial_mode TEXT NOT NULL DEFAULT 'SIM' CHECK(financial_mode='SIM'),PRIMARY KEY(run_id,intent_id));
CREATE TABLE IF NOT EXISTS sim_positions(run_id TEXT NOT NULL,position_id TEXT NOT NULL,status TEXT NOT NULL,opened_ms REAL NOT NULL,closed_ms REAL,margin_raw TEXT NOT NULL,payload_json TEXT NOT NULL,financial_mode TEXT NOT NULL DEFAULT 'SIM' CHECK(financial_mode='SIM'),PRIMARY KEY(run_id,position_id));
CREATE TABLE IF NOT EXISTS sim_trades(run_id TEXT NOT NULL,position_id TEXT NOT NULL,opened_ms REAL NOT NULL,closed_ms REAL NOT NULL,entry_raw TEXT NOT NULL,exit_raw TEXT NOT NULL,margin_raw TEXT NOT NULL,leverage INTEGER NOT NULL,cash_raw TEXT NOT NULL,fee_raw TEXT NOT NULL,reason TEXT,model_hash TEXT NOT NULL,financial_mode TEXT NOT NULL DEFAULT 'SIM' CHECK(financial_mode='SIM'),PRIMARY KEY(run_id,position_id));
CREATE TABLE IF NOT EXISTS sim_forecasts(run_id TEXT NOT NULL,boot TEXT NOT NULL,sequence INTEGER NOT NULL,at_ms REAL NOT NULL,model_hash TEXT NOT NULL,input_hash TEXT NOT NULL,payload_json TEXT NOT NULL,permission TEXT NOT NULL DEFAULT 'TIMING_ONLY_NOT_LIVE',PRIMARY KEY(run_id,boot,sequence,model_hash));
CREATE TABLE IF NOT EXISTS public_evidence(run_id TEXT NOT NULL,boot TEXT NOT NULL,sequence INTEGER NOT NULL,kind TEXT NOT NULL,symbol TEXT,recv_ms REAL NOT NULL,source_ms REAL,payload_hash TEXT NOT NULL,cohort_json TEXT NOT NULL,attribution TEXT NOT NULL DEFAULT 'PUBLIC_NOT_OWN_VIRTUAL_FILL',PRIMARY KEY(run_id,boot,sequence));
CREATE TABLE IF NOT EXISTS quality_events(id INTEGER PRIMARY KEY,run_id TEXT NOT NULL,at_ms REAL NOT NULL,kind TEXT NOT NULL,payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS market_seconds(run_id TEXT NOT NULL,second_ms INTEGER NOT NULL,symbol TEXT NOT NULL,venue TEXT NOT NULL,quote_n INTEGER NOT NULL,book_n INTEGER NOT NULL,bid_min REAL,bid_max REAL,ask_min REAL,ask_max REAL,last_bid TEXT,last_ask TEXT,last_recv_ms REAL,PRIMARY KEY(run_id,second_ms,symbol,venue));
CREATE TABLE IF NOT EXISTS market_daily(run_id TEXT NOT NULL,day_ms INTEGER NOT NULL,symbol TEXT NOT NULL,venue TEXT NOT NULL,quote_n INTEGER NOT NULL,book_n INTEGER NOT NULL,seconds_n INTEGER NOT NULL,bid_min REAL,bid_max REAL,ask_min REAL,ask_max REAL,PRIMARY KEY(run_id,day_ms,symbol,venue));
CREATE TABLE IF NOT EXISTS raw_segments(id INTEGER PRIMARY KEY,run_id TEXT NOT NULL,file TEXT NOT NULL UNIQUE,sha256 TEXT NOT NULL,bytes INTEGER NOT NULL,first_ms REAL,last_ms REAL,event_n INTEGER NOT NULL,coverage TEXT NOT NULL,protected INTEGER NOT NULL,context_json TEXT NOT NULL,deleted_ms REAL);
CREATE INDEX IF NOT EXISTS sim_decisions_time ON sim_decisions(run_id,second_ms);
CREATE INDEX IF NOT EXISTS sim_trades_time ON sim_trades(closed_ms);
CREATE INDEX IF NOT EXISTS public_evidence_cohort ON public_evidence(symbol,kind,recv_ms);
CREATE INDEX IF NOT EXISTS sim_forecasts_time ON sim_forecasts(run_id,at_ms);
CREATE INDEX IF NOT EXISTS quality_events_kind_time ON quality_events(kind,at_ms);
-- prune() runs on every raw flush (~1/s): live rows only, so a partial index avoids full scans of the growing table.
CREATE INDEX IF NOT EXISTS raw_segments_live ON raw_segments(protected,last_ms) WHERE deleted_ms IS NULL;
